window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-26901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1322 na letra μ · nº geral 26901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. μετῴκησα) 1 mudar de residência; migrar para, ac. 2 estabelecer-se em outro lugar, dat. 3 participar, como habitante, do usufruto de, gen. 4 residir como imigrante em um país estrangeiro; ser meteco. 〈μέτοικος〉</p></section></article>\n<article id=\"entry-dgp-26902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοίκησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1323 na letra μ · nº geral 26902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">transferência; migração. 〈μετοικέω〉</p></section></article>\n<article id=\"entry-dgp-26903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1324 na letra μ · nº geral 26903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 habitação ou residência comunitária; coabitação 2 transferência de país; emigração 3 estabelecimento de um estrangeiro em uma cidade; residência em país estrangeiro 4 situação e direitos de um estrangeiro domiciliado; condição de meteco 5 bíbl. deportação; exílio. 〈μέτοικος〉</p></section></article>\n<article id=\"entry-dgp-26904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1325 na letra μ · nº geral 26904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μετοικίσω, át. μετοικιῶ) 1 transferir de uma residência para outra 2 conduzir uma colônia 3 pôr alguém, ac., fora de si ♦ méd. 4 emigrar. 〈μέτοικος〉</p></section></article>\n<article id=\"entry-dgp-26905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικικός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1326 na letra μ · nº geral 26905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que goza dos direitos de meteco 2 estrangeiro domiciliado. 〈μέτοικος〉</p></section></article>\n<article id=\"entry-dgp-26906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοίκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1327 na letra μ · nº geral 26906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 taxa de doze dracmas imposta aos estrangeiros domiciliados em Atenas 2 pl. festa ateniense, no mês Boedrômion, em memória da reunião dos vários burgos em uma só cidade (συνοικία). 〈μέτοικος〉</p></section></article>\n<article id=\"entry-dgp-26907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1328 na letra μ · nº geral 26907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 transferência de país; emigração 2 deportação. 〈μετοικίζω〉</p></section></article>\n<article id=\"entry-dgp-26908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικιστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1329 na letra μ · nº geral 26908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de μετοικίζω.</p></section></article>\n<article id=\"entry-dgp-26909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1330 na letra μ · nº geral 26909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">quem povoa de estrangeiros uma cidade. 〈μετοικίζω〉</p></section></article>\n<article id=\"entry-dgp-26910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικιῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1331 na letra μ · nº geral 26910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. át. de μετοικίζω.</p></section></article>\n<article id=\"entry-dgp-26911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικοδομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1332 na letra μ · nº geral 26911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">construir em outro lugar.</p></section></article>\n<article id=\"entry-dgp-26912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτοικος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1333 na letra μ · nº geral 26912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estrangeiro que vem estabelecer-se em um lugar, gen.: μέτοικοι δόμων ésql. habitantes da casa 2 em Atenas, meteco, estrangeiro domiciliado na cidade mediante uma taxa 3 que reside com; que vive com, dat. 〈μετά, οἶκος〉</p></section></article>\n<article id=\"entry-dgp-26913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοιστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1334 na letra μ · nº geral 26913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de μεταφέρω.</p></section></article>\n<article id=\"entry-dgp-26914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοίσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1335 na letra μ · nº geral 26914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de μεταφέρω.</p></section></article>\n<article id=\"entry-dgp-26915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοίχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1336 na letra μ · nº geral 26915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. μετῳχόμην) 1 ir com; acompanhar; seguir 2 ir em direção a; ir encontrar; abordar, ac. 3 perseguir, ac.</p></section></article>\n<article id=\"entry-dgp-26916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοκλάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1337 na letra μ · nº geral 26916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apoiar-se ora sobre um pé, ora sobre outro; passar de um lugar a outro 2 cambalear; oscilar.</p></section></article>\n<article id=\"entry-dgp-26917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετόν</h1><div class=\"entry-meta\"><span>DGP · ordem 1338 na letra μ · nº geral 26917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. n. de μέτειμι1.</p></section></article>\n<article id=\"entry-dgp-26918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετονομάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1339 na letra μ · nº geral 26918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. μετωνόμασα; pas. aor. μετωνομάσθην, perf. μετωνόμασμαι) chamar por outro nome.</p></section></article>\n<article id=\"entry-dgp-26919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετόπισθε</h1><div class=\"entry-meta\"><span>DGP · ordem 1340 na letra μ · nº geral 26919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μετόπισθεν adv. 1 atrás; para trás 2 em seguida; mais tarde ♦ prep. 3 atrás de, gen. 〈μετά, ὄπισθε〉</p></section></article>\n<article id=\"entry-dgp-26920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοπωρινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1341 na letra μ · nº geral 26920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do fim do outono; do outono; outonal. 〈μετόπωρον〉</p></section></article>\n<article id=\"entry-dgp-26921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετόπωρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1342 na letra μ · nº geral 26921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fim de outono; outono. 〈μετά, ὀπώρα〉</p></section></article>\n<article id=\"entry-dgp-26922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετορμίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1343 na letra μ · nº geral 26922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = μεθορμίζω.</p></section></article>\n<article id=\"entry-dgp-26923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετουσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1344 na letra μ · nº geral 26923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 participação; comunidade 2 possessão 3 dominação.</p></section></article>\n<article id=\"entry-dgp-26924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοχή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1345 na letra μ · nº geral 26924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 participação; comunidade 2 Gram. particípio. 〈μετέχω〉</p></section></article>\n<article id=\"entry-dgp-26925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοχλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1346 na letra μ · nº geral 26925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deslocar com uma alavanca; deslocar com esforço.</p></section></article>\n<article id=\"entry-dgp-26926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτοχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1347 na letra μ · nº geral 26926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que participa de, gen.: μέτ. τοῦ φόνου eur. cúmplice do assassínio 2 bíbl. amigo; companheiro. 〈μετέχω〉</p></section></article>\n<article id=\"entry-dgp-26927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1348 na letra μ · nº geral 26927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μετρήσω, aor. ἐμέτρησα, perf. μεμέτρηκα) 1 tomar a medida de; medir, ac.: μετ. τὴν χώρην ὀρ­γυιῇσι her. medir um país em braças 2 percorrer; cruzar: μετ. πέλαγος hom. medir, i.e., percorrer o mar 3 medir; avaliar: τῇ γαστρὶ μετ. τὴν εὐδαιμονίαν dem. medir a felicidade pelo estômago 4 atribuir uma medida de algo, ac., a alguém, dat.: πώλοισι χόρτον μετρ. eur. dar forragem aos cavalos 5 Jur. fornecer: τὸν σῖτον τῇ μητρὶ μετρ. dem. fornecer alimento à mãe 6 crist. escrever em versos ♦ méd. 7 percorrer algo, ac.: μετρήσασθαι ἅλα mos. percorrer o mar, μετρούμενον ἴχνη τὰ κείνου sóf. seguindo (com os olhos) as pegadas dele 8 receber uma medida de, ac.: τὸν σῖτον μετρεῖσθαι plut. receber uma medida de de trigo. 〈μέτρον〉</p></section></article>\n<article id=\"entry-dgp-26928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτρημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1349 na letra μ · nº geral 26928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 distância medida; área 2 parte medida ou atribuída 3 ração de soldado 4 soldo. 〈μετρέω〉</p></section></article>\n<article id=\"entry-dgp-26929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτρησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1350 na letra μ · nº geral 26929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de medir; medição. 〈μετρέω〉</p></section></article>\n<article id=\"entry-dgp-26930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετρητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1351 na letra μ · nº geral 26930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de μετρέω.</p></section></article>\n<article id=\"entry-dgp-26931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετρητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1352 na letra μ · nº geral 26931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quem toma medidas; medidor 2 em Atenas, ânfora, medida para líquidos (aprox. 39 litros). 〈μετρέω〉</p></section></article>\n<article id=\"entry-dgp-26932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετριάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1353 na letra μ · nº geral 26932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser moderado; agir com moderação; mostrar moderação em algo, dat., ἐν, ἐπί e dat., περί, πρός e ac. 2 crist. ser humilde 3 ser de média</p></section></article>\n<article id=\"entry-dgp-26933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1354⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1354 na letra μ · nº geral 26933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">s proporções, de tamanho médio 4 tornar-se medíocre; enfraquecer-se 5 moderar; conter; controlar. 〈μέτριος〉 μετρικός, ή, όν 1 que concerne à medida dos versos; métrico ♦ ὁ μετρικός 2 especialista em metrificação 3 poeta ♦ ἡ μετρική 4 a métrica. 〈μέτρον〉</p></section></article>\n<article id=\"entry-dgp-26934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1355 na letra μ · nº geral 26934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μέτριος.</p></section></article>\n<article id=\"entry-dgp-26935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετριοπάθεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1356 na letra μ · nº geral 26935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">controle ou moderação nas paixões ou nos sentimentos; equanimidade. 〈μέτριος, πάθος〉</p></section></article>\n<article id=\"entry-dgp-26936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετριοπαθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1357 na letra μ · nº geral 26936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ter controle sobre paixões ou sentimentos; ser equânime 2 crist. ser humilde 3 bíbl. compadecer-se moderadamente de, dat.</p></section></article>\n<article id=\"entry-dgp-26937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετριοπότης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1358 na letra μ · nº geral 26937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que bebe moderadamente. 〈μέτριος, πίνω〉</p></section></article>\n<article id=\"entry-dgp-26938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτριος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1359 na letra μ · nº geral 26938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 médio; mediano (altura, tamanho) 2 suficiente: μέτριον χρόνον xen. durante um tempo suficiente, μέτρια ὕδατα plut. quantidade de água suficiente 3 simples; comum: μετρία ἐσθής tuc. veste simples, μὴ μέτριος αἰών sóf. existência incomum (na qual tudo é excessivo, tanto o bem como o mal) 4 de condição mediana: μέτ. ἀνήρ xen. homem de condição mediana, μέτρια κεκτῆσθαι xen. possuir uma fortuna mediana 5 moderado; comedido; regrado: μέτ. ἀνήρ plat. homem comedido em linguagem e conduta, μέτ. πρὸς τοὺς ὑπηκόους tuc. moderado em relação a seus próprios assuntos ♦ μέτρια adv. 6 com moderação; com modéstia: μέτρια τὰ περὶ σεαυτοῦ λέγεις luc. falas sobre ti próprio com modéstia ♦ οἱ μέτριοι 7 os homens de condição média</p></section></article>\n<article id=\"entry-dgp-26939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1360⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1360 na letra μ · nº geral 26939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">♦ τὸ μέτριον 8 vida de duração mediana ou ordinária ♦ τὸ μέτριον, τὰ μέτρια 9 a justa medida: ἐπὶ μετρίοις tuc. em condições moderadas, περαιτέρω τοῦ μετρίου xen. para além da justa medida ♦ τὰ μέτρια 10 moderação na vida; vida modesta. 〈μέτρον〉 μετριότης, ητος (ἡ) 1 justa medida; moderação 2 quantidade justa; grau justo 3 condição modesta. 〈μέτριος〉</p></section></article>\n<article id=\"entry-dgp-26940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετρίως</h1><div class=\"entry-meta\"><span>DGP · ordem 1361 na letra μ · nº geral 26940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com medida ou com moderação; moderadamente: οὐ μετρίως plut. sem moderação; em alto grau ou com excesso 2 pobremente.</p></section></article>\n<article id=\"entry-dgp-26941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1362 na letra μ · nº geral 26941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 instrumento para medir; uma medida 2 vara para medir 3 medida para secos e molhados 4 regra; lei; cânone; norma 5 quantidade medida ou espaço medido; comprimento; duração: μέτρα κελεύθου hom. o comprimento de um caminho; μέτρ. ὅρμου hom. extensão ou limites de um porto, μέτ. ἥβη hom. a duração da juventude, a idade da juventude 6 Pros. medida de um verso 7 Pros., pl. verso 8 justa medida: μέτρῳ πίνειν beber moderadamente, κατὰ μέτρον hes. com medida; como convém, ὑπὲρ τὸ μέτρον teóg. além da medida, οὐκ ἐκ μέτρου n.t. sem medida.</p></section></article>\n<article id=\"entry-dgp-26942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετωνυμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1363 na letra μ · nº geral 26942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 emprego de um nome por outro 2 Ret. metonímia. 〈μετά, ὄνομα〉</p></section></article>\n<article id=\"entry-dgp-26943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετωπηδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 1364 na letra μ · nº geral 26943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de frente; em linha. 〈μέτωπον, -δόν〉</p></section></article>\n<article id=\"entry-dgp-26944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτωπον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1365 na letra μ · nº geral 26944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fronte; testa 2 parte proeminente; frente; fachada de construção 3 frente de um exército, de um bando 4 armadura frontal, parte anterior e saliente do capacete. 〈μετά, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-26945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετωποσώφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1366 na letra μ · nº geral 26945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος que traz a sabedoria estampada na face. 〈μέτωπον, σώφρων〉</p></section></article>\n<article id=\"entry-dgp-26946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μευ</h1><div class=\"entry-meta\"><span>DGP · ordem 1367 na letra μ · nº geral 26946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ép. e jôn. de ἐγώ.</p></section></article>\n<article id=\"entry-dgp-26947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέχρι</h1><div class=\"entry-meta\"><span>DGP · ordem 1368 na letra μ · nº geral 26947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μέχρις prep. 1 (lugar, tempo, quantidade) até, gen.: μ. τοῦδε tuc., μ. τούτου xen. até agora, até este tempo, μ. ἐμεῦ her. até minha época, μ. οὗ át. até o ponto em que, tanto que, todo o tempo em que, até, μ. οὗ μέχρι οὗ ἀγορῆς διαλύσιος her. até a dissolução da assembléia, μ. μὲν δὴ ἕξ ἢ ἑπτακαίδεκα ἐτῶν xen. até dezesseis ou dezessete anos, μ. ἐνταῦθα xen. até aqui, μ. νῦν d.s. até agora, μ. μὲν ποῖ; xen. até onde?, μ. εἰς, μ. ἐπί até a, μ. ἕως até que ♦ conj. 2 até que, com ind., subj. ou inf.</p></section></article>\n<article id=\"entry-dgp-26948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μή</h1><div class=\"entry-meta\"><span>DGP · ordem 1369 na letra μ · nº geral 26948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">partíc. de neg. não</p></section></article>\n<article id=\"entry-dgp-26949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1370⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1370 na letra μ · nº geral 26949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 para marcar proibição ou conselho, com imper., ou com inf. em or. dependente de verbo que exprima a idéia de neg., ou depois de verbos que exprimam uma idéia neg. como proibir, impedir, abster-se de, guardar-se de etc.</p></section></article>\n<article id=\"entry-dgp-26950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1371⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1371 na letra μ · nº geral 26950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2 em advertências ou expressando temor, de medo que</p></section></article>\n<article id=\"entry-dgp-26951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1372⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1372 na letra μ · nº geral 26951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3 iniciando inter. ind., se… não</p></section></article>\n<article id=\"entry-dgp-26952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1373⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1373 na letra μ · nº geral 26952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">4 depois de verbos que exprimem temor, produzindo or. afirm.</p></section></article>\n<article id=\"entry-dgp-26953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1374⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1374 na letra μ · nº geral 26953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">5 depois de conj. final, produzindo or. neg., a fim de que não</p></section></article>\n<article id=\"entry-dgp-26954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μὴ οὐ</h1><div class=\"entry-meta\"><span>DGP · ordem 1375 na letra μ · nº geral 26954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\"></p></section></article>\n<article id=\"entry-dgp-26955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1376⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1376 na letra μ · nº geral 26955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">6 exprime a neg. com dúvida, em or. compl. de verbo de temor ou de apreensão, que não</p></section></article>\n<article id=\"entry-dgp-26956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1377⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1377 na letra μ · nº geral 26956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">7 em or. compl. de verbos que significam proibir, impedir, evitar, precedidos de neg. ou de sent. neg.</p></section></article>\n<article id=\"entry-dgp-26957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1378⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1378 na letra μ · nº geral 26957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">8 em or. compl. de verbos ou expressões que indicam impossibilidade, inconveniência, relutância</p></section></article>\n<article id=\"entry-dgp-26958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μή</h1><div class=\"entry-meta\"><span>DGP · ordem 1379 na letra μ · nº geral 26958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com outras partíc.</p></section></article>\n<article id=\"entry-dgp-26959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1380⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1380 na letra μ · nº geral 26959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">9 μὴ ἀλλά não, pelo contrário; μὴ γάρ pois bem, então não; μὴ δή por certo, não; μὴ μήν verdadeiramente, não; μὴ ὅπως ou μὴ ὅτι (elíptico por μὴ λέγε ὅτι) não digas que, não se diga que (contrastando com um membro da or. posterior iniciado por ἀλλά ou com um membro da or. anterior iniciado por οὐδέ ou por καὶ οὐ); μή ποτε adv. jamais; μή που a fim de que… de modo algum; μή πω ainda não, não mais; μή πω πρίν não antes que; μηπώποτε de modo nenhum; μήπως a fim de que… não, de nenhum modo; se… não mais em alguma coisa; μή τι ou μήτι não mais… então, certamente… não; μή τοι ou μήτοι verdadeiramente não, certamente não</p></section></article>\n<article id=\"entry-dgp-26960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1381⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1381 na letra μ · nº geral 26960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 μή μ’ ἐρέθιζε hom. não me irrites, μή τις ἀκουσάτω hom. que ninguém ouça, μή τις ὀπίσσω τετράφθω hom. que ninguém volte atrás, καταρνεῖ μὴ δεδρακέναι τάδε; sóf. negas ter feito isto?, μὴ φθονήσῃς plat. não sejas malvado</p></section></article>\n<article id=\"entry-dgp-26961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1382⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1382 na letra μ · nº geral 26961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2 σὺ μὲν νῦν αὖτις ἀπόστιχε, μή τι νοήσῃ Ἥρη hom. agora afasta-te e retorna para que Hera não te perceba, αἷμα μὴ σοῖς ἐξομόρξωμαι πέπλοις hom. [temo] espargir sangue sobre tuas vestes</p></section></article>\n<article id=\"entry-dgp-26962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1383⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1383 na letra μ · nº geral 26962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3 ὄφρα ἴδωμεν μή τοι κοιμήσωνται hom. para vermos se não dormem, οὐδέ τι ἴδμεν μή πως καὶ διὰ νύκτα μενοι­νήσωσι μάχεσθαι hom. nem sabemos se eles não pensam em atacar-nos durante a noite</p></section></article>\n<article id=\"entry-dgp-26963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1384⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1384 na letra μ · nº geral 26963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">4 φοβεῖται μὴ τὰ ἔσχατα πάθῃ xen. (teu pai) teme passar pela experiência extrema, ἐδεδοίκειν μὴ ἐν τῷ κρατῆρι φάρ­μακα μεμιγμένα εἴη xen. temo que na taça tenha sido misturada uma droga</p></section></article>\n<article id=\"entry-dgp-26964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1385⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1385 na letra μ · nº geral 26964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">5 βουλὴν ὑποθησόμεθα… ὡς μὴ πάντες ὄλωνται hom. faremos uma sugestão a fim de que não morram todos</p></section></article>\n<article id=\"entry-dgp-26965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1386⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1386 na letra μ · nº geral 26965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">6 δείδω, μὴ οὔ τίς τοι ὑπόσχηται τόδε ἔργον hom. temo que ninguém te prometa um serviço semelhante a este, ἐφοβεῖτο μὴ οὐ</p></section></article>\n<article id=\"entry-dgp-26966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δύναιτο ἐξελθεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1387 na letra μ · nº geral 26966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">xen. tinha medo de que não pudesse sair, οὐ τοῦτο δέδοικα, μὴ οὐ</p></section></article>\n<article id=\"entry-dgp-26967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κ ἔχω ὅ τι δῶ ἑκάστῳ φίλων, ἀλλὰ μὴ οὐ</h1><div class=\"entry-meta\"><span>DGP · ordem 1388 na letra μ · nº geral 26967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\"></p></section></article>\n<article id=\"entry-dgp-26968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κ ἔχω οἷς δῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1389 na letra μ · nº geral 26968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">xen. meu temor não é que não tenha o que dar para cada um dos amigos, mas que não tenha a quem dar 7 οὐκέτι ἀνεβάλλοντο μὴ οὐ</p></section></article>\n<article id=\"entry-dgp-26969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τὸ πᾶν μηχανήσασθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1390 na letra μ · nº geral 26969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">her. não mais hesitavam em maquinar todo o possível, οὐδὲν ἐδύνατο ἀντέχειν μὴ οὐ</p></section></article>\n<article id=\"entry-dgp-26970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χαρίζεσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1391 na letra μ · nº geral 26970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">xen. (Astíages) não podia deixar de ser agradável (a Ciro) 8 ἄνδρα δ’ οὐκ ἔστι μὴ οὐ</p></section></article>\n<article id=\"entry-dgp-26971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακὸν ἔμμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1392 na letra μ · nº geral 26971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sim. não há como o homem não ser mau, οὐκ ἔστι τοι οὐδεμία μηχανὴ μὴ οὐ</p></section></article>\n<article id=\"entry-dgp-26972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κ ἀπολωλέναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1393 na letra μ · nº geral 26972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">her. não há para ti possibilidade de não morrer, οὐδεὶς ἂν τολμήσειεν μὴ οὐ</p></section></article>\n<article id=\"entry-dgp-26973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χρῆσθαι τῷ νόμῳ</h1><div class=\"entry-meta\"><span>DGP · ordem 1394 na letra μ · nº geral 26973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ant. ninguém ousaria não seguir a lei 9 μὴ ὅτι ἰδιώτην τινὰ, ἀλλὰ τὸν μέγαν βασιλέα plat. não somente um indivíduo qualquer, mas o grande rei, μὴ ὅπως ὀρχεῖσθαι ἐν ῥυθμῷ, ἀλλ’ οὐδ’ ὀρθοῦσθαι ἐδύνασθε xen. não apenas [não poderíeis] dançar no ritmo, mas também não poderíeis nem sequer manter-vos eretos, οὐδὲ ἀναπνεῖν, μὴ ὅτι λέγειν τι δυνάμεθα xen. nem respirar podemos, mais ainda não podemos dizer alguma coisa, ὀμοῦμαι μή ποτε τῆς εὐνῆς ἐπιβῆμεναι hom. juro que jamais subi em seu leito.</p></section></article>\n<article id=\"entry-dgp-26974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμά</h1><div class=\"entry-meta\"><span>DGP · ordem 1395 na letra μ · nº geral 26974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de modo algum 2 jamais. 〈μηδαμός〉</p></section></article>\n<article id=\"entry-dgp-26975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμῇ</h1><div class=\"entry-meta\"><span>DGP · ordem 1396 na letra μ · nº geral 26975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo algum. 〈μηδαμός〉</p></section></article>\n<article id=\"entry-dgp-26976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1397 na letra μ · nº geral 26976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de nenhum lugar. 〈μηδαμός, -θεν〉</p></section></article>\n<article id=\"entry-dgp-26977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμόθι</h1><div class=\"entry-meta\"><span>DGP · ordem 1398 na letra μ · nº geral 26977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em nenhuma parte. 〈μηδαμός, -θι〉</p></section></article>\n<article id=\"entry-dgp-26978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμοῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 1399 na letra μ · nº geral 26978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em parte alguma. 〈μηδαμός〉</p></section></article>\n<article id=\"entry-dgp-26979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1400 na letra μ · nº geral 26979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só pl. ninguém. 〈μηδέ, ἀμός〉</p></section></article>\n<article id=\"entry-dgp-26980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμόσε</h1><div class=\"entry-meta\"><span>DGP · ordem 1401 na letra μ · nº geral 26980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em parte alguma. 〈μηδαμός, -σε〉</p></section></article>\n<article id=\"entry-dgp-26981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμοῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 1402 na letra μ · nº geral 26981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em lugar algum: μηδ. τῶν ὄντων plat. em nenhum lugar do mundo 2 em nada; de modo algum: μηδ. νομίζεσθαι ésql. não ser conhecido de modo algum, μηδ. εἶναι xen. não ter nenhum valor. 〈μηδαμός〉</p></section></article>\n<article id=\"entry-dgp-26982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1403 na letra μ · nº geral 26982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de forma alguma; de modo nenhum. 〈μη­δαμός〉</p></section></article>\n<article id=\"entry-dgp-26983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδέ</h1><div class=\"entry-meta\"><span>DGP · ordem 1404 na letra μ · nº geral 26983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj. 1 nem, corresp. a οὐδέ em construções que exigem a neg. μή ♦ adv. 2 nem ao menos. 〈μή, δέ〉</p></section></article>\n<article id=\"entry-dgp-26984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μήδεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1405 na letra μ · nº geral 26984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medéia, mulher de Jasão.</p></section></article>\n<article id=\"entry-dgp-26985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδείς, μηδεμία, μηδέν</h1><div class=\"entry-meta\"><span>DGP · ordem 1406 na letra μ · nº geral 26985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. μηδενός, μεδεμίας, μηδε­νός (em construções que exigem a neg. μή) pron. 1 nem ao menos um; nenhum; ninguém, nenhuma pessoa; no n. nenhuma coisa; nada ♦ μηδέν adv. 2 em nada; de modo algum; μηδέν ἦττον át. não menos, μηδὲν μᾶλλον át. não mais ♦ ὁ μηδείς 3 quem nada é; um ninguém; uma nulidade ♦ μηδέν e τὸ μηδέν 4 nada; o nada. 〈μηδέ, εἷς〉</p></section></article>\n<article id=\"entry-dgp-26986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδεμία</h1><div class=\"entry-meta\"><span>DGP · ordem 1407 na letra μ · nº geral 26986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μηδείς.</p></section></article>\n<article id=\"entry-dgp-26987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδέποτε</h1><div class=\"entry-meta\"><span>DGP · ordem 1408 na letra μ · nº geral 26987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μηδέ ποτε adv. jamais; não mais.</p></section></article>\n<article id=\"entry-dgp-26988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδέπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1409 na letra μ · nº geral 26988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. não ainda.</p></section></article>\n<article id=\"entry-dgp-26989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδεπώποτε</h1><div class=\"entry-meta\"><span>DGP · ordem 1410 na letra μ · nº geral 26989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. não mais; jamais.</p></section></article>\n<article id=\"entry-dgp-26990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδέτερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1411 na letra μ · nº geral 26990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nem um nem outro; nenhum dos dois.</p></section></article>\n<article id=\"entry-dgp-26991\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδετέρωσε</h1><div class=\"entry-meta\"><span>DGP · ordem 1412 na letra μ · nº geral 26991</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em nenhum dos lados; em nenhuma das partes; nem de um lado nem de outro. 〈μηδέτερος, -σε〉</p></section></article>\n<article id=\"entry-dgp-26992\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μὴ δή</h1><div class=\"entry-meta\"><span>DGP · ordem 1413 na letra μ · nº geral 26992</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μή.</p></section></article>\n<article id=\"entry-dgp-26993\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μηδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1414 na letra μ · nº geral 26993</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Média, região da Pérsia.</p></section></article>\n<article id=\"entry-dgp-26994\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1415 na letra μ · nº geral 26994</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser ou estar do lado dos medos ou dos persas. 〈Μῆδοι〉</p></section></article>\n<article id=\"entry-dgp-26995\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μηδικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1416 na letra μ · nº geral 26995</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de medo ou da Média ♦ ἡ Μηδική 2 a Média ♦ τὰ Μηδικά 3 as guerras Médicas. 〈Μηδία〉</p></section></article>\n<article id=\"entry-dgp-26996\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μηδικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1417 na letra μ · nº geral 26996</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. à maneira dos medos; à maneira média</p></section></article>\n<article id=\"entry-dgp-26997\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1418⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1418 na letra μ · nº geral 26997</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">. Μήδιος, α, ον da Média; médio. 〈Μῆδος4〉</p></section></article>\n<article id=\"entry-dgp-26998\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μηδίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1419 na letra μ · nº geral 26998</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mulher da Média. 〈Μῆδοι〉</p></section></article>\n<article id=\"entry-dgp-26999\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1420 na letra μ · nº geral 26999</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adesão ao medos ou dos persas. 〈μηδίζω〉</p></section></article>\n<article id=\"entry-dgp-27000\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήδομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1421 na letra μ · nº geral 27000</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μήσομαι, aor. ἐμησάμην, perf. desus.) 1 revolver na mente; meditar; pensar em, ac. 2 imaginar; inventar 3 tramar; maquinar algo, ac., contra alguém, ac., dat. ou ἐπί e dat. 4 trabalhar; preparar algo, ac., para alguém, dat.: μήδ. μέλι plut. preparar mel 5 cuidar de; ocupar-se de, gen.</p></section></article>\n";
